@section('scripts')<script>$(function(){let token=@json(session('api_token'));$.ajax({url:'/api/dashboard',headers:{Authorization:'Bearer '+token}}).done(function(data){let i=data.indicadores;$('#stats strong').each(function(n){if(n<4)$(this).text([i.total,i.pendentes,i.atendimento,i.resolvidos][n])});$('#nivel-1').text(i.nivel_1);$('#nivel-2').text(i.nivel_2);$('#nivel-3').text(i.nivel_3);let common={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}};if(data.categorias.length)new Chart($('#categoryChart'),{type:'bar',data:{labels:data.categorias.map(x=>x.nome),datasets:[{data:data.categorias.map(x=>x.total),backgroundColor:'#246bce',borderRadius:5}]},options:{...common,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});else{$('#categoryChart').hide();$('#category-empty').removeClass('d-none')}if(data.prioridades.length)new Chart($('#priorityChart'),{type:'doughnut',data:{labels:data.prioridades.map(x=>x.nome),datasets:[{data:data.prioridades.map(x=>x.total),backgroundColor:['#dc3545','#fd7e14','#198754']}]},options:common});else{$('#priorityChart').hide();$('#priority-empty').removeClass('d-none')}if(data.meses.length)new Chart($('#monthChart'),{type:'line',data:{labels:data.meses.map(x=>x.mes),datasets:[{data:data.meses.map(x=>x.total),borderColor:'#246bce',backgroundColor:'#246bce22',fill:true,tension:.3}]},options:{...common,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});else{$('#monthChart').hide();$('#month-empty').removeClass('d-none')}}).fail(()=>location.href='/login')});</script>@endsection